// Shared evidence is workspace-scoped, opt-in, and independent of individual tool drafts.
const EFS={workspace:null,context:null,revision:0,epoch:0,pending:null,run:null,actions:new Map(),insertedQ:null,insertedContext:null};
function efSourceWorkspace(){return String(window.CL_ACTIVE_CHANNEL||'general')}
function efSourceStorageKey(){return 'cl_source_context_v1_'+encodeURIComponent(EFS.workspace)}
function efSourceClone(c){return c?JSON.parse(JSON.stringify(c)):null}
function efSourceEmpty(){return {text:'',kind:'pasted-text',source:'Your pasted source text',note:'No timing or transcript origin verified.',vid:'',video_url:'',input_url:'',cues:[]}}
function efSourceCurrent(){
 const key=efSourceWorkspace();
 if(EFS.workspace===key)return EFS.context;
 EFS.workspace=key;EFS.revision++;EFS.pending=null;EFS.insertedQ=null;EFS.insertedContext=null;
 if(EFS.run){EFS.run=null;ST.busy=false;}
 EFS.context=efSourceEmpty();
 try{
  const c=JSON.parse(localStorage.getItem(efSourceStorageKey())||'null');
  if(c&&typeof c.text==='string'&&['subtitles','screen-ocr','pasted-text','pasted-subtitles','pasted-ocr'].includes(c.kind)){
   EFS.context={...efSourceEmpty(),text:c.text,kind:c.kind,source:String(c.source||''),note:String(c.note||''),vid:String(c.vid||''),video_url:String(c.video_url||''),input_url:String(c.input_url??c.video_url??''),cues:efSourceCues(c)};
  }
 }catch(e){/* Unavailable or corrupt storage must not prevent local use. */}
 efSourceRender();return EFS.context;
}
function efSourceSave(){
 if(EFS.workspace!==efSourceWorkspace())return;
 try{localStorage.setItem(efSourceStorageKey(),JSON.stringify(EFS.context));return true}
 catch(e){efSourceStatus('Source is available this session, but browser storage could not save it.');return false}
}
function efSourceVideo(q){
 q=String(q).trim();
 if(/^[\w-]{11}$/.test(q))return q;
 if(/\s/.test(q))return null;
 try{const u=new URL(q.startsWith('http')?q:'https://'+q);if(!['youtube.com','www.youtube.com','m.youtube.com','youtu.be','www.youtu.be','youtube-nocookie.com','www.youtube-nocookie.com'].includes(u.hostname)||!['http:','https:'].includes(u.protocol))return null;return extractVideo(q)}catch(e){return null}
}
function efSourceCues(c){
 if(/ocr/.test(c.kind||''))return [];
 return Array.isArray(c.cues)?c.cues.filter(x=>Number.isFinite(x.start)&&Number.isFinite(x.end)&&x.start>=0&&x.end>x.start&&typeof x.text==='string').map(x=>({start:x.start,end:x.end,text:x.text})):[];
}
function efSourceNormalize(r,method,q){
 if(!r||r.error)throw Error(r?.error||'Source request failed.');
 if(typeof r.text!=='string'||!r.text.trim())throw Error('No source text available. Paste text, retry subtitles, or explicitly choose screen OCR (local or API).');
 if(method==='subtitles'&&/ocr|screen/i.test(String(r.kind||'')))throw Error('Subtitles were requested, but screen OCR was returned. Choose OCR explicitly to use screen text.');
 const c={text:r.text.trim(),kind:method==='ocr'?'screen-ocr':'subtitles',source:String(r.source||(method==='ocr'?(r.engine==='api'?'Gemini vision API screen OCR':'Local screen OCR'):'Available YouTube subtitles')),note:String(r.note||''),vid:String(r.vid||efSourceVideo(q)||''),video_url:q,input_url:q,cues:[]};
 c.cues=efSourceCues({...r,kind:c.kind});
 if(method==='ocr')c.note+=' Screen text only, not spoken transcript. No source timing is inferred.';
 return c;
}
function efSourceTimedText(c){return c.cues?.length?c.cues.map(x=>efSrtTime(x.start)+' --> '+efSrtTime(x.end)+'\n'+x.text).join('\n\n'):c.text}
function efSourceMetadata(c){return {kind:c.kind,source:c.source,note:c.note,vid:c.vid,video_url:c.video_url,characters:c.text.length,timing:/ocr/.test(c.kind)?'none':c.cues?.length?'original cues':'only timestamps explicitly present in supplied text'}}
function efSourceBlock(c){return 'SOURCE MATERIAL '+JSON.stringify(efSourceMetadata(c))+'\n'+efSourceTimedText(c)+'\nEND SOURCE MATERIAL'}
function efSourceRequireTiming(c,q){
 if(c&&/ocr/.test(c.kind))throw Error('Screen OCR is not timed spoken captions. For chapters, supply original timed subtitles; screen clocks cannot be used as chapter timing.');
 const text=c?efSourceTimedText(c):q;
 if(!/(?:^|\n)\s*\d+(?::\d{2}){1,2}(?:[.,]\d+)?\s+\S/.test(text))throw Error('Chapter generation needs supplied caption timestamps. Paste timed SRT/VTT or fetch timed subtitles; timings cannot be invented.');
}
function efToolSnapshot(){return {id:ST.tool,epoch:EFS.epoch,form:$('#studio-form'),workspace:efSourceWorkspace()}}
function efToolCurrent(s){return s.id===ST.tool&&s.epoch===EFS.epoch&&s.form===$('#studio-form')&&s.workspace===efSourceWorkspace()&&s.form?.isConnected}
async function efToolAction(name,work){
 efSourceCurrent();const snapshot=efToolSnapshot(),previous=EFS.actions.get(name);
 if(previous&&efToolCurrent(previous))return;
 EFS.actions.set(name,snapshot);
 try{await work(()=>EFS.actions.get(name)===snapshot&&efToolCurrent(snapshot))}
 catch(e){if(efToolCurrent(snapshot))toast(e.message||'Request failed.','bad')}
 finally{if(EFS.actions.get(name)===snapshot)EFS.actions.delete(name)}
}
function efSourceStatus(message){const e=$('#esc-status');if(e)e.textContent=message}
function efSourceRender(preserveInputs=false){
 const panel=$('#esc-panel');if(!panel||!EFS.context)return;
 const c=EFS.context;
 if(!preserveInputs){$('#esc-video').value=c.input_url??c.video_url;$('#esc-text').value=c.text;}
 $('#esc-kind').value=/ocr/.test(c.kind)?'pasted-ocr':/subtitles/.test(c.kind)?'pasted-subtitles':'pasted-text';
 $('#esc-provenance').textContent='Workspace: '+EFS.workspace+' · '+c.kind+' · '+c.source+(c.vid?' · Video '+c.vid:'')+'\n'+c.note;
 $('#esc-preview').textContent=c.text?efSourceTimedText(c).slice(0,1800)+(c.text.length>1800?'\n[Preview truncated; full source remains above.]':''):'No shared source yet.';
 panel.querySelectorAll('[data-source-fetch]').forEach(b=>b.disabled=!!EFS.pending);
 panel.querySelectorAll('[data-source-insert]').forEach(b=>b.disabled=!c.text.trim()||!!EFS.pending);
}
function efSourceEdited(type){
 // A workspace may have changed while this form was mounted; never transfer the old text.
 if(EFS.workspace!==efSourceWorkspace()){efSourceCurrent();efSourceStatus('Workspace changed; its own source has been loaded.');return}
 EFS.revision++;EFS.pending=null;
 const c=EFS.context;
 if(type==='video'){c.input_url=$('#esc-video').value.trim();}
 else{
  const kind=type==='kind'?$('#esc-kind').value:(/ocr/.test(c.kind)?'pasted-ocr':/subtitles/.test(c.kind)?'pasted-subtitles':'pasted-text');
  EFS.context={...efSourceEmpty(),text:$('#esc-text').value,kind,video_url:c.video_url,input_url:c.input_url,source:'Your pasted / edited '+(kind==='pasted-ocr'?'screen OCR text':kind==='pasted-subtitles'?'subtitles':'source text'),note:kind==='pasted-ocr'?'Screen text, not spoken transcript. No timing inferred.':'User-supplied text; preserve only explicitly supplied timestamps.'};
 }
 efSourceRender(true);efSourceStatus('');efSourceSave();
}
async function efSourceFetch(method){
 efSourceCurrent();if(EFS.pending)return;
 const q=$('#esc-video')?.value.trim();
 if(!efSourceVideo(q))return efSourceStatus('Enter a valid YouTube video URL or ID first.');
 const token={...efToolSnapshot(),revision:EFS.revision,panel:$('#esc-panel')};
 const engine=method==='ocr'?($('#esc-ocr-engine')?.value||'local'):undefined;
 if(!efOcrConsent(engine))return;
 EFS.pending=token;efSourceRender();efSourceStatus(method==='ocr'?(engine==='api'?'Reading screen OCR via Gemini vision (API); this is not spoken transcript…':'Reading local screen OCR only; this is not spoken transcript…'):'Fetching available subtitles; no OCR fallback…');
 try{
  const raw=await efRequest('source-context',{q,method,...(engine?{engine}:{})});
  if(EFS.pending!==token||!efToolCurrent(token)||token.revision!==EFS.revision||token.panel!==$('#esc-panel'))return;
  EFS.context=efSourceNormalize(raw,method,q);EFS.revision++;efSourceStatus('Source ready. Use an explicit insert/attach action below.');efSourceSave();
 }catch(e){if(EFS.pending===token&&efToolCurrent(token))efSourceStatus(e.message||'Source fetch failed; existing source was preserved.')}
 finally{if(EFS.pending===token){EFS.pending=null;if(efToolCurrent(token))efSourceRender();}}
}
function efSourceClear(){
 efSourceCurrent();EFS.revision++;EFS.pending=null;EFS.context=efSourceEmpty();
 try{localStorage.removeItem(efSourceStorageKey())}catch(e){efSourceStatus('Cleared for this session; browser storage could not be updated.');efSourceRender();return}
 efSourceRender();efSourceStatus('Shared source cleared. Previously inserted tool text is unchanged.');
}
function efSourceInsert(target){
 efSourceCurrent();const c=efSourceClone(EFS.context);if(!c.text.trim()||EFS.pending)return;
 const t=STUDIO_TOOLS.find(x=>x.id===ST.tool);
 if(target==='context'&&t.mode==='ai'){
  const e=$('#ef-context'),block=efSourceBlock(c);if(!e)return;
  if(!e.value.includes(block))e.value+=(e.value.trim()?'\n\n':'')+block;
  EFS.insertedContext={block,context:c};
 }else if(target==='q'&&(t.mode==='ai'||t.id==='title-score')){
  const e=$('#sf-q');if(!e)return;
  if(t.id==='chapters'){try{efSourceRequireTiming(c,c.text)}catch(err){efSourceStatus(err.message);return}}
  const area=$('#esc-text'),selected=area.value.slice(area.selectionStart,area.selectionEnd);
  if(t.id==='title-score'){e.value=selected||c.text;EFS.insertedQ=null;}
  else{
   const append=!['summary','chapters','translate','script-review'].includes(t.id);
   const block=efSourceBlock(c);
   if(append){if(!e.value.includes(block))e.value+=(e.value.trim()?'\n\n':'')+block;}
   else e.value=efSourceTimedText(c);
   EFS.insertedQ={value:e.value.trim(),context:c,append};
  }
 }else return;
 proCaptureTool();efSourceStatus('Source inserted with provenance. Review it before running; nothing was generated.');
}
function efSourceMount(){
 const form=$('#studio-form'),t=STUDIO_TOOLS.find(x=>x.id===ST.tool);if(!form||!t)return;
 const panel=document.createElement('details');panel.id='esc-panel';panel.className='pro-method';
 // This template is static. All pasted/fetched text is assigned via value/textContent.
 panel.innerHTML='<summary>Shared source context · subtitles, screen OCR (local or API) or pasted text</summary><p class="studio-muted">Optional evidence shared by tools in this own-channel workspace. Nothing is auto-filled. OCR reads screen text with the local engine or Gemini vision (API), not speech; generation sends attached text to your configured AI provider.</p><label>Video URL or ID<input id="esc-video" type="text" autocomplete="off"></label><div class="studio-toolbar"><button type="button" data-source-fetch="subtitles">Fetch subtitles</button><button type="button" data-source-fetch="ocr">Read screen OCR</button></div><label>Screen OCR engine<select id="esc-ocr-engine"><option value="local">Local · on-device, free</option><option value="api">API · Gemini vision (key quota)</option></select></label><label>Pasted text provenance<select id="esc-kind"><option value="pasted-text">General supplied text (not verified transcript)</option><option value="pasted-subtitles">Supplied subtitles / timed captions</option><option value="pasted-ocr">Supplied screen OCR (not speech)</option></select></label><label>Shared source text<textarea id="esc-text" rows="5"></textarea></label><p id="esc-provenance" class="studio-muted"></p><details><summary>Source preview</summary><pre id="esc-preview" class="studio-output"></pre></details><div id="esc-insert" class="studio-toolbar"></div><button type="button" id="esc-clear">Clear shared source</button><p id="esc-status" role="status" aria-live="polite"></p>';
 form.querySelector('#tool-run').before(panel);
 panel.querySelectorAll('[data-source-fetch]').forEach(b=>b.onclick=()=>efSourceFetch(b.dataset.sourceFetch));
 $('#esc-video').oninput=()=>efSourceEdited('video');$('#esc-text').oninput=()=>efSourceEdited('text');$('#esc-kind').onchange=()=>efSourceEdited('kind');$('#esc-clear').onclick=efSourceClear;
 const actions=$('#esc-insert');
 function insertButton(label,target){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.sourceInsert=target;b.onclick=()=>efSourceInsert(target);actions.append(b)}
 if(t.mode==='ai'){
  insertButton(['summary','chapters','translate','script-review'].includes(t.id)?'Replace source input':'Append source to topic / brief','q');
  insertButton('Attach to requirements / evidence','context');
  const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.id='esc-attach';check.checked=false;label.append(check,document.createTextNode(' Attach shared source on generation (opt-in)'));actions.append(label);
 }else if(t.id==='title-score')insertButton('Replace title input with selected / pasted text','q');
 else{const note=document.createElement('p');note.className='studio-muted';note.textContent='Reference only for this tool. URL, image and calculator inputs are not changed.';actions.append(note)}
 efSourceCurrent();efSourceRender();
}
const efSourceOpen=toolOpen;
toolOpen=function(id){
 if(!STUDIO_TOOLS.some(t=>t.id===id))return;
 EFS.epoch++;EFS.pending=null;EFS.insertedQ=null;EFS.insertedContext=null;
 if(EFS.run){EFS.run=null;ST.busy=false;}
 efSourceOpen(id);efSourceMount();
};
// Focus catches workspace changes even when the parent retains the same tool DOM.
document.addEventListener('focusin',()=>{if($('#esc-panel'))efSourceCurrent()});
const efSourceRenderResult=renderToolResult;
renderToolResult=function(t,r){
 efSourceRenderResult(t,r);const el=$('#tool-result');if(!el)return;
 for(const sm of [r.summary,...(r.profiles||[]).map(p=>p.summary)].filter(Boolean)){
  el.insertAdjacentHTML('beforeend',table(['Sample scope / coverage','Value'],[['Source scope',sm.source_scope||'Returned sample only'],['Views available / sampled',sm.views_known_videos==null?'Unknown':sm.views_known_videos+' / '+sm.sample],['Engagement denominator (views)',sm.engagement_denominator_views],['Engagement excluded videos',sm.engagement_excluded_videos],['Like-rate samples / denominator views',sm.like_rate_videos==null?'Unknown':sm.like_rate_videos+' / '+sm.like_rate_denominator_views],['Comment-rate samples / denominator views',sm.comment_rate_videos==null?'Unknown':sm.comment_rate_videos+' / '+sm.comment_rate_denominator_views],['Observed publication dates',sm.published_from&&sm.published_to?sm.published_from+' → '+sm.published_to:'Unavailable'],['Duration unknown videos',sm.duration_unknown_videos]])+snote(sm.engagement_method||'Rates exclude unavailable counts; durations do not confirm Shorts.'));
 }
 if(r.source_context?.length){const provenance=document.createElement('pre');provenance.className='studio-output';provenance.textContent='Source provenance used for this draft\n'+JSON.stringify(r.source_context,null,2);el.append(provenance)}
};

async function efVideoPackRun(){
 const q=svalue('q').trim(),vid=efSourceVideo(q);
 if(!vid)return toast('Paste a YouTube video URL or ID first.','warn');
 if(ST.busy)return;
 const run=efToolSnapshot(),button=$('#tool-run'),result=$('#tool-result');
 EFS.run=run;ST.busy=true;ST.result=null;proToolActions();button.disabled=true;button.textContent='Reading video…';
 result.innerHTML=sempty('Reading public video metadata','Fetching the real title, description, tags and counts from the YouTube Data API.');
 try{
  const r=await efRequest('video',{q});
  if(!efToolCurrent(run))return;
  efSetResult({feature:'video-pack',video:r.video,vid,transcript:null,ocr:null,source:r.source||'YouTube Data API',note:'Full description and all tags exactly as returned by YouTube. Applied keywords use the same video tag list; no separate keyword field is exposed by the public API.'});
 }catch(e){
  if(efToolCurrent(run)){const error=document.createElement('div');error.className='err';error.setAttribute('role','alert');error.textContent=e.message||'Could not read this video. Check the link and your API settings.';result.replaceChildren(error)}
 }finally{
  if(EFS.run===run){EFS.run=null;ST.busy=false;}
  if(efToolCurrent(run)){button.disabled=false;button.textContent='Run tool';proToolActions();proCaptureTool();}
 }
}
