 return '<div class="vp-read"><div class="vp-section-head"><h3>Spoken transcript</h3><div class="studio-toolbar"><button class="sm" onclick="cpText(ST.result.transcript.text)">Copy</button><button class="sm" onclick="sdownload(\'transcript.txt\',ST.result.transcript.text,\'text/plain\')">Download TXT</button>'+(tr.cues.length?'<button class="sm" onclick="sdownload(\'captions.srt\',efSrt(ST.result.transcript.cues),\'text/plain\')">Download SRT</button>':'')+'</div></div><p class="studio-muted">'+tr.text.length+' characters · '+(tr.cached?'saved local subtitle cache':'fresh YouTube subtitles')+(tr.cues.length?' · '+tr.cues.length+' timed cues':'')+'</p><pre class="studio-output vp-transcript">'+sx(tr.text)+'</pre>'+(tr.cues.length?'':snote('No saved cue timing for this transcript; SRT export is unavailable. Re-fetch in the Transcript tool for timed cues.'))+'</div>';
