 return '<div class="vp-read"><div class="vp-section-head"><h3>Screen OCR · '+(api?'API (Gemini vision)':'local')+'</h3><div class="studio-toolbar"><button class="sm" onclick="cpText(ST.result.ocr.text)">Copy</button><button class="sm" onclick="sdownload(\'screen-ocr.txt\',ST.result.ocr.text,\'text/plain\')">Download TXT</button></div></div><p class="studio-muted">'+o.text.length+' characters · '+(o.cached?(api?'saved API OCR cache':'saved local OCR cache'):(o.frames!=null?o.frames+' frames read '+(api?'via Gemini vision':'locally'):'fresh frame OCR'))+(o.step!=null?' · about '+o.step+'s between sampled frames':'')+' · on-screen text, not speech</p><pre class="studio-output vp-transcript">'+sx(o.text)+'</pre></div>';
