function efPackOcrLabel(){const b=$('#vp-ocr-btn');if(b&&!ST.busy)b.textContent='Read screen OCR · '+($('#vp-ocr-engine')?.value==='api'?'API':'local');}
function efPackHtml(r){
 const v=r.video;
 let h='<div class="vp-head"><h3>'+sx(v.title)+'</h3><p class="studio-muted">'+sx(v.channel||'')+' · <a href="https://www.youtube.com/watch?v='+encodeURIComponent(v.id)+'" target="_blank" rel="noopener">Open on YouTube</a></p></div>';
 h+='<div class="studio-metrics vp-metrics">'+smetric('Views',sn(v.views))+smetric('Likes',sn(v.likes))+smetric('Comments',sn(v.comments))+smetric('Duration',efClock(v.seconds))+smetric('Published',v.published?new Date(v.published).toLocaleDateString():'—')+'</div>';
 h+='<div class="vp-section"><div class="vp-section-head"><h3>Real description</h3><div class="studio-toolbar"><button class="sm" onclick="cpText(ST.result.video.description)">Copy</button><button class="sm" onclick="sdownload(\'description.txt\',ST.result.video.description,\'text/plain\')">Download TXT</button></div></div><pre id="vp-description-text" class="studio-output vp-description"></pre><p class="studio-muted">'+v.description.length+' characters · exactly as returned by YouTube</p></div>';
 h+='<div class="vp-section"><div class="vp-section-head"><h3>Applied tags · '+v.tags.length+'</h3><div class="studio-toolbar"><button class="sm" onclick="cpText(ST.result.video.tags.join(\', \'))">Copy</button><button class="sm" onclick="sdownload(\'video-tags.txt\',ST.result.video.tags.join(\', \'),\'text/plain\')">Download TXT</button></div></div>'+(v.tags.length?'<div class="vp-tags">'+v.tags.map(t=>'<span class="studio-chip">'+sx(t)+'</span>').join('')+'</div>':'<p class="studio-muted">This video has no public tags.</p>')+'<p class="studio-muted">API-style tag character budget: '+efTagLength(v.tags)+' / 500 · exactly the tags the creator applied, verbatim and complete</p></div>';
 h+='<div class="vp-section"><div class="vp-section-head"><h3>Applied keywords · '+v.tags.length+'</h3><div class="studio-toolbar"><button class="sm" onclick="cpText(ST.result.video.tags.join(\', \'))">Copy</button><button class="sm" onclick="sdownload(\'video-keywords.txt\',ST.result.video.tags.join(\', \'),\'text/plain\')">Download TXT</button></div></div><pre id="vp-keywords-text" class="studio-output vp-description"></pre>'+snote('Same creator-set list as Tags above (YouTube snippet.tags), with original spelling and order. The public API exposes no separate video keywords field; no words are guessed from the title or description.')+'</div>';
 h+='<div class="vp-section vp-actions"><h3>Read the video content</h3><div class="studio-toolbar"><button id="vp-transcript-btn" class="go" onclick="efPackTranscript()">Get spoken transcript</button><label class="vp-engine">OCR engine<select id="vp-ocr-engine" onchange="efPackOcrLabel()"><option value="local">Local · on-device, free</option><option value="api">API · Gemini vision (key quota)</option></select></label><button id="vp-ocr-btn" class="go" onclick="efPackOcr()">Read screen OCR · local</button></div>'+snote('Transcript = available YouTube subtitles (spoken captions). Screen OCR = on-screen text read with the local engine (free, on-device) or Gemini vision (API, uses your key quota); it is not speech.')+'<div id="vp-transcript">'+(r.transcript?efPackTranscriptHtml(r.transcript):'')+'</div><div id="vp-ocr">'+(r.ocr?efPackOcrHtml(r.ocr):'')+'</div></div>';
 return h;
}
async function efPackTranscript(){
 const r=ST.result,vid=r?.vid,box=$('#vp-transcript'),btn=$('#vp-transcript-btn');
 if(!vid||!box||!btn||ST.busy||EFS.actions.has('pack-transcript'))return;
 const run=efToolSnapshot();
 EFS.actions.set('pack-transcript',run);btn.disabled=true;btn.textContent='Fetching subtitles…';
 box.innerHTML='<p class="studio-muted" role="status">Fetching available YouTube subtitles…</p>';
 try{
  const raw=await efRequest('transcript',{q:vid});
  if(!efToolCurrent(run)||EFS.actions.get('pack-transcript')!==run)return;
  if(!raw.text?.trim())throw Error('No subtitle text was returned for this video.');
  r.transcript={text:raw.text,cues:Array.isArray(raw.cues)?raw.cues:[],cached:!!raw.cached};
  box.innerHTML=efPackTranscriptHtml(r.transcript);
  toast('Spoken transcript ready.','ok');proCaptureTool();
 }catch(e){
  if(efToolCurrent(run)&&EFS.actions.get('pack-transcript')===run)box.innerHTML='<div class="err" role="alert">'+sx(e.message||'Subtitles unavailable.')+'</div>'+snote('If this video has no captions, choose local or API Screen OCR for on-screen text.');
 }finally{
  if(EFS.actions.get('pack-transcript')===run){EFS.actions.delete('pack-transcript');if(efToolCurrent(run)){btn.disabled=false;btn.textContent='Get spoken transcript';}}
 }
}
async function efPackOcr(){
 const r=ST.result,vid=r?.vid,box=$('#vp-ocr'),btn=$('#vp-ocr-btn');
 if(!vid||!box||!btn||ST.busy)return;
 const run=efToolSnapshot(),mainBtn=$('#tool-run'),engine=$('#vp-ocr-engine')?.value||'local';
 if(!efOcrConsent(engine))return;
 EFS.run=run;ST.busy=true;proToolActions();btn.disabled=true;btn.textContent='Reading screen text…';
 if(mainBtn){mainBtn.disabled=true;mainBtn.textContent='Screen OCR running…';}
 box.innerHTML='<p class="studio-muted" role="status">Downloading the smallest video format for frame sampling, then reading with '+(engine==='api'?'Gemini vision (API, your key quota)':'your local OCR engine')+'. First read can take a few minutes; repeats use the saved cache.</p><p class="studio-muted" id="vp-ocr-progress" role="status"></p>';
 const timer=setInterval(async()=>{if(!efToolCurrent(run)||!$('#vp-ocr-progress'))return clearInterval(timer);try{const p=await j('/api/trp?id='+encodeURIComponent(vid));const el=$('#vp-ocr-progress');if(!el||!efToolCurrent(run))return clearInterval(timer);el.textContent=p.none?'':p.stage==='ocr'?'Frame '+(p.done|0)+' of '+(p.total|0)+(engine==='api'?' read via Gemini vision…':' read locally…'):'Downloading video for frame sampling…'}catch(e){}},4000);
 try{
  const raw=await efRequest('source-context',{q:vid,method:'ocr',engine});
  if(!efToolCurrent(run))return;
  const c=efSourceNormalize(raw,'ocr',vid);
  r.ocr={text:c.text,frames:raw.frames??null,step:raw.step??null,cached:!!raw.cached,engine:raw.engine||engine};
  box.innerHTML=efPackOcrHtml(r.ocr);
  toast('Screen OCR ready — on-screen text, not speech.','ok');proCaptureTool();
 }catch(e){
  if(efToolCurrent(run))box.innerHTML='<div class="err" role="alert">'+sx(e.message||'Screen OCR failed.')+'</div>'+snote(engine==='api'?'API OCR needs a Gemini key and quota; check the key or switch to the local engine.':'Check local ffmpeg and the OCR engine, then retry.');
 }finally{
  clearInterval(timer);
  if(EFS.run===run){EFS.run=null;ST.busy=false;}
  if(efToolCurrent(run)){btn.disabled=false;efPackOcrLabel();if(mainBtn){mainBtn.disabled=false;mainBtn.textContent='Run tool';}proToolActions();proCaptureTool();}
 }
}
function efEvidenceHtml(r){
 const e=r.evidence;
 if(!e)return r.ground_error?'<div class="vp-evidence"><h3>Live grounding unavailable</h3>'+snote(r.ground_error+' The draft below used your brief only.')+'</div>':'';
 return '<div class="vp-evidence"><h3>Real YouTube evidence behind this draft</h3><p class="studio-muted">Live search query: “'+sx(e.q)+'”</p><div class="studio-metrics">'+smetric('Sample videos',e.rows.length)+smetric('Median views',sn(e.median_views))+'</div>'+videoTable(e.rows.slice(0,8))+(e.rows.length>8?'<details><summary>All '+e.rows.length+' evidence videos</summary>'+videoTable(e.rows)+'</details>':'')+snote(e.note)+'</div>';
}
function efIdeaStarters(rows,topic,med){
 const pool=rows.filter(v=>v.title&&v.views!=null).sort((a,b)=>b.views-a.views);
 const strong=med!=null?pool.filter(v=>v.views>=med):[];
 const formats=[
  {label:'Listicle',test:t=>/(?:^|\s)\d+\s+(?:ways|things|mistakes|tips|reasons|rules|secrets|habits|tools|apps|sites|tricks)\b/.test(t)||/^top\s+\d+/.test(t),make:x=>(x.title.match(/\d+/)||['7'])[0]+' '+topic+' mistakes worth avoiding'},
  {label:'How-to / tutorial',test:t=>/\bhow to\b|\btutorial\b|\bstep by step\b/.test(t),make:()=>'How to approach '+topic+' step by step'},
  {label:'Comparison',test:t=>/\bvs\.?\b|\bversus\b|\bcompared\b/.test(t),make:()=>topic+' compared: which option actually fits you'},
  {label:'Review / test',test:t=>/\breview\b|\btested\b|\btest\b|\bhands.on\b/.test(t),make:()=>topic+' tested: what holds up in practice'},
  {label:'Personal experiment',test:t=>/^i\s|\bi tried\b|\bmy\b|\bi bought\b|\bi spent\b/.test(t),make:()=>'I tried '+topic+' — here is what changed'},
  {label:'Explainer',test:t=>/^(?:why|what|when|who)\b|\bexplained\b/.test(t),make:()=>'Why '+topic+' works differently than you expect'},
  {label:'Promise / payoff',test:t=>t.includes(':'),make:()=>topic+': what most people get wrong'},
  {label:'Challenge / constraint',test:t=>/\bchallenge\b|\b24 hours\b|\bi survived\b|\bwithout\b/.test(t),make:()=>topic+' with one constraint: what breaks first'}
 ];
 const out=[];
 for(const f of formats){
  const example=(strong.length?strong:pool).find(v=>f.test(v.title.toLowerCase()))||pool.find(v=>f.test(v.title.toLowerCase()));
  if(example)out.push({format:f.label,idea:f.make(example),example,strong:med!=null&&example.views>=med});
 }
 if(out.length<3){for(const v of pool){if(out.length>=3)break;if(!out.some(o=>o.example.id===v.id))out.push({format:'Observed angle',idea:topic+' — a focused look at what “'+v.title+'” promises',example:v,strong:med!=null&&v.views>=med})}}
 return out.slice(0,10);
}
async function efLocalIdeas(){
 const q=(efVal('evidence-topic')||svalue('q')).trim();
 if(!q)return toast('Enter a topic first.','warn');
 return efToolAction('local-ideas',async current=>{
  const r=await efRequest('search',{q,language:'en'});
  if(!current())return;
  if(!r.rows?.length)throw Error('The live search returned no videos for this topic.');
  const ideas=efIdeaStarters(r.rows,q,r.median_views??null);
  const text=ideas.map((x,i)=>(i+1)+'. ['+x.format+'] '+x.idea+'\n   Evidence: “'+x.example.title+'” — '+sn(x.example.views)+' views · https://www.youtube.com/watch?v='+x.example.id).join('\n\n');
  efSetResult({feature:'local-ideas',html:'<div class="vp-evidence"><h3>Real YouTube evidence behind these starters</h3><div class="studio-metrics">'+smetric('Sample videos',r.rows.length)+smetric('Median views',sn(r.median_views))+'</div>'+videoTable(r.rows.slice(0,8))+'</div><h3>Idea starters · adapted locally, no AI</h3>'+table(['Format','Your starter idea','Evidence title','Views','vs sample median'],ideas.map(x=>[x.format,x.idea,x.example.title,sn(x.example.views),x.strong?'At/above median':'Below median']))+'<pre class="studio-output">'+sx(text)+'</pre><div class="studio-toolbar"><button onclick="cpText(ST.result.text)">Copy starters</button><button onclick="sdownload(\'idea-starters.txt\',ST.result.text,\'text/plain\')">Download TXT</button></div>',text,ideas,rows:r.rows,median_views:r.median_views,source:'Local pattern adaptation from a live YouTube search sample',note:'No AI was used. Formats were detected in real returned titles and adapted to your topic; views are observed lifetime counts, not forecasts. Verify facts and feasibility before producing.'});
 });
}

